lock_dropbox_file.afterResponse:
var entries = response.entries;
if (!Array.isArray(entries) || entries.length === 0) throw new Error('Dropbox returned no result entry for lock the file.');
var entry = entries[0];
if (typeof entry === 'object' && entry !== null && entry['.tag'] === 'failure') throw new Error('Dropbox could not lock the file: ' + JSON.stringify(entry.failure));
return entry;

